package com.maonaroda.mao_na_roda;
import android.os.Bundle; import android.view.*; import androidx.annotation.*; import androidx.fragment.app.Fragment; import androidx.navigation.fragment.NavHostFragment; import com.google.android.material.bottomsheet.BottomSheetDialog; import android.widget.*;
public class OnboardingFragment extends Fragment { public View onCreateView(LayoutInflater i,ViewGroup p,Bundle b){return i.inflate(R.layout.fragment_onboarding,p,false);} public void onViewCreated(@NonNull View v,Bundle b){super.onViewCreated(v,b); v.findViewById(R.id.continueButton).setOnClickListener(x->complete()); v.findViewById(R.id.createButton).setOnClickListener(x->auth(false)); v.findViewById(R.id.signInButton).setOnClickListener(x->auth(true)); v.findViewById(R.id.howButton).setOnClickListener(x->HowItWorksSheet.show(getParentFragmentManager()));} void complete(){requireContext().getSharedPreferences("prefs",0).edit().putBoolean("onboarding_completed",true).apply(); NavHostFragment.findNavController(this).navigate(R.id.action_onboarding_to_home);} void auth(boolean signIn){Bundle a=new Bundle();a.putBoolean("signIn",signIn);NavHostFragment.findNavController(this).navigate(R.id.action_onboarding_to_auth,a);} }
